INSERT INTO public.story_chapter_i18n (chapter_id, locale, title, body)
SELECT ch.id, 'en',
  $body$The Longest Night$body$,
  $body$On the worst night of the summer, two people were dying, and they lived at opposite ends of the village, and he had one totem.

He did not choose.

He pulled it out of the floor, ran it to the other house, pushed it in beside the second bed, counted, pulled it out, and ran back. The street is four hundred steps long. He ran it forty-one times, all night, in the rain, with a sword on his back.

In the morning both of them were still breathing.

He sat down on the step and did not get up for a while.$body$
FROM public.story_chapter ch
JOIN public.story_issue i ON i.id = ch.issue_id
WHERE i.slug = $body$juggernaut-sixty-one-carvings$body$ AND ch.chapter_index = 9;

