SELECT i.id, 'en',
  $body$Marci's Battle Speech$body$,
  $body$Marci has a few words before the battle.$body$
FROM public.story_issue i
WHERE i.slug = $body$marci-battle-speech$body$;

INSERT INTO public.story_chapter (issue_id, chapter_index)
SELECT i.id,
  1
FROM public.story_issue i
WHERE i.slug = $body$marci-battle-speech$body$;

INSERT INTO public.story_chapter_i18n (chapter_id, locale, title, body)
SELECT ch.id, 'en',
  $body$Before the Battle$body$,
  $body$Tweet. Tweet tweet. Fweeeet.

Tweet tweet tweet, tweet tweet, tweet tweet tweet tweet. Fweet. Tweet tweet tweet, tweet, tweet tweet. Fweeeet, tweet tweet tweet. Twe twe tweet. Tweet tweet, fweet tweet tweet, tweet tweet tweet tweet. Tweet tweet tweet. Fweet tweet. Tweet.

Tweet? Fweeeet. Tweet tweet tweet, tweet tweet tweet tweet, tweet tweet. Fweet tweet, tweet tweet, tweet tweet tweet. Tweet tweet tweet tweet. Twe twe tweet. Tweet tweet, fweet, tweet tweet tweet.

Tweet tweet. Fweet. Tweet tweet tweet, tweet tweet. Fweeeet. Tweet tweet tweet tweet tweet, tweet tweet, tweet. Fweet, tweet tweet, tweet tweet tweet. Twe twe tweet.

Tweet tweet.$body$
FROM public.story_chapter ch
JOIN public.story_issue i ON i.id = ch.issue_id
WHERE i.slug = $body$marci-battle-speech$body$ AND ch.chapter_index = 1;

COMMIT;
